) as v(legado_id, ticket, parte, valor_nota, valor, criado_em, lancado_em,
        rateio, faturado, pago, legado_caminho, legado_alerta)
join chamados c on c.numero = v.ticket::int
left join lateral (
  select cc.id_trilogo,
         (select an.arquivo_sha256 from chamado_anexos an
           where an.custo_id = cc.id and an.colecao = 'orcamento'
           order by an.id limit 1) as sha
    from chamado_custos cc
   where cc.chamado_id = c.id and cc.valor = v.valor::numeric
   order by cc.id_trilogo limit 1) m on true
on conflict (cliente_id, legado_id) where legado_id is not null do nothing;

commit;
